class Node:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next

def build(values):
    head = None
    for x in reversed(values):
        head = Node(x, head)
    return head

def to_list(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out

def reverse(head):
    prev = None
    while head:
        head.next, prev, head = prev, head, head.next
    return prev

def middle(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
    return slow.val

h = build([1, 2, 3, 4, 5])
print("list:", to_list(h))
print("middle:", middle(h))
print("reversed:", to_list(reverse(h)))

def fact(n):
    return 1 if n == 0 else n * fact(n - 1)

def power(x, n):
    if n == 0:
        return 1
    half = power(x, n // 2)
    return half * half * (x if n % 2 else 1)

def hanoi(n, src, dst, via, moves):
    if n == 0:
        return
    hanoi(n - 1, src, via, dst, moves)
    moves.append((src, dst))
    hanoi(n - 1, via, dst, src, moves)

