import sys

class Node:
    def __init__(self, val):
        self.val, self.left, self.right = val, None, None

data = sys.stdin.read().split()
n = int(data[0])
root = None
for v in map(int, data[1:1 + n]):
    if root is None:
        root = Node(v)
        continue
    cur = root
    while True:
        if v == cur.val:
            break
        if v < cur.val:
            if cur.left is None:
                cur.left = Node(v)
                break
            cur = cur.left
        else:
            if cur.right is None:
                cur.right = Node(v)
                break
            cur = cur.right

height = 0
order = []
stack = [(root, 1)]
while stack:
    node, depth = stack.pop()
    order.append(str(node.val))
    height = max(height, depth)
    if node.right:
        stack.append((node.right, depth + 1))
    if node.left:
        stack.append((node.left, depth + 1))
print(height)
print(" ".join(order))

