def count_components(adj, n):
    seen, comps = [False] * (n + 1), 0
    for s in range(1, n + 1):
        if not seen[s]:
            comps += 1
            stack, seen[s] = [s], True
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not seen[v]:
                        seen[v] = True; stack.append(v)
    return comps

