import heapq
def dijkstra(adj, s):
    INF = float("inf")
    dist = [INF] * len(adj)
    dist[s] = 0
    pq = [(0, s)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue            # stale entry
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(pq, (dist[v], v))
    return dist

from functools import lru_cache

@lru_cache(maxsize=None)     # memoization (top-down)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

def fib_table(n):            # tabulation (bottom-up)
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
print(fib(80), fib_table(80))

def min_coins(coins, amount):
    INF = float("inf")
    dp = [0] + [INF] * amount
    for x in range(1, amount + 1):
        for c in coins:
            if c <= x and dp[x - c] + 1 < dp[x]:
                dp[x] = dp[x - c] + 1
    return dp[amount] if dp[amount] != INF else -1

print(min_coins([1, 3, 4], 6))   # 2
print(min_coins([2], 3))         # -1

