from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)
print("fib(90) =", fib(90))

def min_coins(coins, amount):
    INF = float("inf")
    dp = [0] + [INF] * amount
    for x in range(1, amount + 1):
        for c in coins:
            if c <= x:
                dp[x] = min(dp[x], dp[x - c] + 1)
    return dp

dp = min_coins([1, 3, 4], 10)
print("min coins for 0..10:", dp)

def lcs(a, b):
    L = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            L[i][j] = L[i-1][j-1] + 1 if a[i-1] == b[j-1] else max(L[i-1][j], L[i][j-1])
    return L[-1][-1]
print("LCS of ABCBDAB and BDCABA:", lcs("ABCBDAB", "BDCABA"))

def max_meetings(meetings):
    chosen, last_end = [], float("-inf")
    for s, e in sorted(meetings, key=lambda m: m[1]):
        if s >= last_end:
            chosen.append((s, e))
            last_end = e
    return chosen

ms = [(1, 4), (3, 5), (0, 6), (5, 7), (3, 9), (5, 9), (6, 10), (8, 11), (8, 12), (2, 14), (12, 16)]
print("chosen:", max_meetings(ms))

def fractional_knapsack(items, cap):
    total = 0.0
    for w, v in sorted(items, key=lambda it: it[1] / it[0], reverse=True):
        take = min(w, cap)
        total += v * take / w
        cap -= take
        if cap == 0:
            break
    return total

print("fractional knapsack:", fractional_knapsack([(10, 60), (20, 100), (30, 120)], 50))

def greedy_coins(coins, amount):
    used = []
    for c in sorted(coins, reverse=True):
        while amount >= c:
            amount -= c; used.append(c)
    return used
print("greedy for {1,3,4}, 6:", greedy_coins([1, 3, 4], 6), "but 3+3 is better")
